-- REMEDIATION_20260801_DIVERSIFY_ACTIVE_CATALOG_TITLES
-- The restored catalogue contains seven real fulfilment modes per material,
-- but all 350 titles previously shared one generated ``X（X·X）`` shell.
-- Preserve every row and fact while presenting each fulfilment mode in a
-- distinct merchant naming convention.
BEGIN;
UPDATE products
SET title = printf('%s｜renovation project detail：%s',
    substr(title, 1, instr(title, '（') - 1),
    substr(title, instr(title, '（') + 1, instr(title, '·') - instr(title, '（') - 1))
WHERE product_id LIKE 'PRD-%' AND title LIKE '%·renovation project detail）';
UPDATE products
SET title = printf('%s - %s【renovation project detail】',
    substr(title, 1, instr(title, '（') - 1),
    substr(title, instr(title, '（') + 1, instr(title, '·') - instr(title, '（') - 1))
WHERE product_id LIKE 'PRD-%' AND title LIKE '%·renovation project detail）';
UPDATE products
SET title = printf('renovation project detail｜%s / %s',
    substr(title, 1, instr(title, '（') - 1),
    substr(title, instr(title, '（') + 1, instr(title, '·') - instr(title, '（') - 1))
WHERE product_id LIKE 'PRD-%' AND title LIKE '%·renovation project detail）';
UPDATE products
SET title = printf('%s【renovation project detail】%s',
    substr(title, 1, instr(title, '（') - 1),
    substr(title, instr(title, '（') + 1, instr(title, '·') - instr(title, '（') - 1))
WHERE product_id LIKE 'PRD-%' AND title LIKE '%·renovation project detail）';
UPDATE products
SET title = printf('renovation project detail：%s—%s',
    substr(title, 1, instr(title, '（') - 1),
    substr(title, instr(title, '（') + 1, instr(title, '·') - instr(title, '（') - 1))
WHERE product_id LIKE 'PRD-%' AND title LIKE '%·renovation project detail）';
UPDATE products
SET title = printf('%s / renovation project detail / %s',
    substr(title, 1, instr(title, '（') - 1),
    substr(title, instr(title, '（') + 1, instr(title, '·') - instr(title, '（') - 1))
WHERE product_id LIKE 'PRD-%' AND title LIKE '%·renovation project detail）';
UPDATE products
SET title = printf('renovation project detail｜%s-%s',
    substr(title, instr(title, '（') + 1, instr(title, '·') - instr(title, '（') - 1),
    substr(title, 1, instr(title, '（') - 1))
WHERE product_id LIKE 'PRD-%' AND title LIKE '%·renovation project detail）';
COMMIT;

-- Final English contract/material facts consumed by the English oracle and rubric.
BEGIN;
